            environ = os.environ
        config = super().load_config(environ=environ)
        self._load_env_vars(config, environ)
        return config

    def _load_env_vars(self, config, environ):
        for key, value in environ.items():
            if key.startswith('THUMBD_'):
                env_key = key[7:].lower()
                if env_key in config:
                    try:
                        config[env_key] = self._convert_value(value)
                    except ConfigError as e:
                        print(e)
                        sys.exit(2)
                else:
                    print(f'Unknown setting: {env_key}')
                    sys.exit(2)

    def _convert_value(self, value):
        try:
            if value.isdigit():
                return int(value)
            elif value.replace('.', '', 1).isdigit():
                return float(value)
            elif value.lower() in ['true', 'yes', 'on', '1']:
                return True
            elif value.lower() in ['false', 'no', 'off', '0']:
                return False
            elif value.strip() == '':
                return []
            else:
                return value.strip()
        except ValueError:
            raise ConfigError(f'Invalid value for setting: {value}')"
  }
